import java.util.Scanner;

public class HeightAllTheSame {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();
        long total = 1L * n * m;
        int mod = 998244353;
        if (total % 2 != 0) {
            long answer = power(r - l + 1, total, mod);
            System.out.println(answer);
        } else {
            int k = r - l + 1;
            int e = r / 2 - l / 2;
            if (l % 2 == 0) e++;
            int o = k - e;
            long ans = power(e + o, total, mod);
            ans = (ans + power(e - o, total, mod)) % mod;
            ans = (ans * inv(2, mod)) % mod;
            System.out.println(ans);
        }
        sc.close();
    }

    static long power(long base, long exp, int mod) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) result = (result * b) % mod;
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }

    static long inv(long a, int m) {
        return power(a, m - 2, m);
    }
}
