#include <bits/stdc++.h>
using namespace std;

long long power(long long base, long long exp, int mod) {
    long long result = 1;
    long long b = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

long long inv(long long a, int m) {
    return power(a, m - 2, m);
}

int main() {
