    long long total = 1LL * n * m;
    int mod = 998244353;
    if (total % 2 != 0) {
        long long answer = power(r - l + 1, total, mod);
        cout << answer << "\n";
    } else {
        int k = r - l + 1;
        int e = r / 2 - l / 2;
        if (l % 2 == 0) e++;
        int o = k - e;
        long long ans = power(e + o, total, mod);
        ans = (ans + power(e - o, total, mod)) % mod;
        ans = (ans * inv(2, mod)) % mod;
        cout << ans << "\n";
    }
    return 0;
}
